import{_ as a,o as s,c as i,aj as n}from"./chunks/framework.CX3tclo0.js";const m=JSON.parse('{"title":"PR Review Agent 的设计","description":"模型负责提意见，插件负责不让它乱发评论。","frontmatter":{"publish":true,"title":"PR Review Agent 的设计","date":"2026-07-05T00:00:00.000Z","category":"Astrcodey","tags":["AI 编程工具","架构设计","插件系统"],"description":"模型负责提意见，插件负责不让它乱发评论。"},"headers":[],"relativePath":"blog/posts/pr-review-agent-design.md","filePath":"blog/posts/pr-review-agent-design.md"}'),p={name:"blog/posts/pr-review-agent-design.md"};function t(o,e,l,r,d,c){return s(),i("div",null,[...e[0]||(e[0]=[n(`<h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>最近写一个 PR Review Agent。写之前想得挺简单：监听 GitHub PR，丢给 agent 看一下，然后把 review 发回去。</p><p>真写起来才发现，最麻烦的不是让模型看代码。模型当然会看，也会说得很像那么回事。麻烦的是它会把不确定的东西说得很肯定，比如编一个行号，或者把一个只能算提醒的问题写成 blocker。</p><p>所以这个插件的设计核心不是“让 AI 自动审代码”。我现在越来越讨厌这种大词。它更像是一个很啰嗦的 worker：把 PR 拉下来，让模型提候选意见，然后自己检查一遍，能发的再发，不能发的收进 summary。</p><p>模型负责提意见。插件负责不信它。</p><h2 id="一个插件" tabindex="-1">一个插件 <a class="header-anchor" href="#一个插件" aria-label="Permalink to &quot;一个插件&quot;">​</a></h2><p>这个东西是外部 s5r 插件。Astrcodey 启动它的时候，实际跑的是：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">astrcode-pr-review-agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> s5r</span></span></code></pre></div><p>启动以后它会注册一个 <code>/pr-review-agent</code> 命令和一个 status tool。真正干活的是后台 poll loop。配置开了 webhook 的话，它还会起一个本地 HTTP receiver。</p><p>也就是说，它更像一个被 Astrcodey 托管的小服务，而不是页面上的一个按钮。</p><p>目前有两个入口：</p><ul><li>PR 评论里提到配置的账号，比如 <code>@whatevertogo review it</code></li><li>配置仓库里新开的 PR</li></ul><p>自动 review 新 PR 这件事我加了一个保护：第一次启用的时候，只 baseline 已经打开的 PR，不立刻全部跑一遍。不然一个仓库几十个 open PR，插件刚上线就开始刷屏，那画面有点丢人。</p><h2 id="队列先行" tabindex="-1">队列先行 <a class="header-anchor" href="#队列先行" aria-label="Permalink to &quot;队列先行&quot;">​</a></h2><p>GitHub 事件进来以后，不会马上开始 review。它会先进入本地状态：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GitHub event / polling</span></span>
<span class="line"><span>        |</span></span>
<span class="line"><span>        v</span></span>
<span class="line"><span>state queue</span></span>
<span class="line"><span>        |</span></span>
<span class="line"><span>        v</span></span>
<span class="line"><span>review worker</span></span></code></pre></div><p>状态都写在 <code>~/.astrcode/pr-review-agent/state.json</code>。这里面有处理过的 comment、见过的 PR、webhook delivery、正在排队的事件、PR session、review memory。</p><p>听起来土，但很好用。</p><p>webhook 和 polling 可能同时来，不能一起改 state。插件会抢 <code>run.lock</code>，抢到了就处理，抢不到的 webhook 事件先写到 spool 文件，下一轮 poll 再导入。没有 Redis，没有数据库，也没有额外 daemon。一个本地 JSON 文件加一个锁，够了。</p><p>我挺喜欢这种设计。它不酷，但失败模式很清楚。</p><h2 id="为什么一个-pr-一个-session" tabindex="-1">为什么一个 PR 一个 session <a class="header-anchor" href="#为什么一个-pr-一个-session" aria-label="Permalink to &quot;为什么一个 PR 一个 session&quot;">​</a></h2><p>每个 PR 都会绑定一个 Astrcode session。</p><p>第一次有人触发 review，插件创建 session。之后同一个 PR 再有人评论，比如“重点看看并发那块”，插件继续把内容塞进同一个 session。</p><p>这里的原因很现实。PR review 通常不是一次性的。第一次 review 可能发现几个问题，作者改完以后又 push，一会儿又有人让你看测试。每次都新建 session，模型就失忆了，只能重新读一遍上下文。</p><p>session 复用也不是绝对安全。旧 session 可能上下文太脏，或者 Astrcodey 服务重启以后状态不完整。所以代码里做了兜底：复用失败就重建 session，再跑一次。</p><h2 id="review-不要一次跑完" tabindex="-1">review 不要一次跑完 <a class="header-anchor" href="#review-不要一次跑完" aria-label="Permalink to &quot;review 不要一次跑完&quot;">​</a></h2><p>一开始我也想过，直接把整个 PR 拼成一个 prompt，让模型一次输出所有 finding。</p><p>后来放弃了。大 PR 会爆上下文，小 PR 也会因为信息太杂导致模型乱抓重点。一次性 review 看起来简单，结果很不可控。</p><p>现在默认走 coverage-first：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>orientation pass</span></span>
<span class="line"><span>file shard pass 1</span></span>
<span class="line"><span>file shard pass 2</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>global pass</span></span>
<span class="line"><span>merge outputs</span></span>
<span class="line"><span>final report</span></span></code></pre></div><p>orientation pass 先看 PR 元信息、仓库记忆和文件清单。它不急着评论，先建立一个大概判断。</p><p>file shard pass 按文件分片。每一片都要求模型返回 <code>files_reviewed</code>，插件用这个判断哪些文件真的被看过。模型如果漏看了某个文件，coverage 里会留下记录。</p><p>global pass 再看跨文件风险。比如状态迁移、API contract、并发边界，这些东西只看一个文件经常看不出来。</p><p>这个流程没有很神秘，就是把“一次性看完”拆成几次比较可控的检查。</p><h2 id="强制-json" tabindex="-1">强制 JSON <a class="header-anchor" href="#强制-json" aria-label="Permalink to &quot;强制 JSON&quot;">​</a></h2><p>这应该是整个插件里最重要的决定。</p><p>模型不能直接写 GitHub 评论。它只能返回 JSON，大概是这些字段：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>confirmed_findings</span></span>
<span class="line"><span>advisory_findings</span></span>
<span class="line"><span>observations</span></span>
<span class="line"><span>verification</span></span>
<span class="line"><span>residual_risk</span></span>
<span class="line"><span>summary</span></span></code></pre></div><p>真正能发 inline comment 的只有 finding。每个 finding 还要过校验：</p><ul><li><code>severity</code> 是不是 P0/P1/P2/P3</li><li><code>confidence</code> 能不能归一化</li><li><code>path</code>、<code>side</code>、<code>line</code> 有没有</li><li>这个 line 是不是 GitHub diff 里能评论的位置</li><li>有没有重复</li><li>数量有没有超过 <code>max_inline_comments</code></li></ul><p>GitHub inline comment 对位置很挑。模型说“第 42 行有问题”不够，42 行必须真的在 PR diff 的 commentable line 里。否则 API 直接拒绝。</p><p>插件会尝试找附近的 RIGHT 行，但不会硬造一个位置。宁愿少发一条，也不要在错误位置上装作很懂。</p><h2 id="提示词怎么写" tabindex="-1">提示词怎么写 <a class="header-anchor" href="#提示词怎么写" aria-label="Permalink to &quot;提示词怎么写&quot;">​</a></h2><p>这个插件的 prompt 不是从零写的。它的底子其实来自我平时用的 <code>reviewnow</code> skill。</p><p><code>reviewnow</code> 做的事情很朴素：先确定 review 范围，再读 diff 和项目上下文，能跑验证就跑验证，然后从几个角度挑真实问题。它不鼓励泛泛而谈，也不鼓励“这里可以更优雅”这种没证据的建议。一个 finding 至少要说清楚几件事：文件行号、问题是什么、影响是什么、证据在哪里、怎么修。</p><p>我把这套东西搬进插件时，删掉了很多不适合自动化的部分。人工 review 可以写一段自然语言，可以临时判断哪些话该说、哪些话不该说。插件不行。插件需要稳定格式，需要能被 Rust 校验，需要能发到 GitHub 的具体位置。</p><p>所以目录里最后变成了几份 prompt：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pr-review-bot.md</span></span>
<span class="line"><span>orientation-review.md</span></span>
<span class="line"><span>file-review.md</span></span>
<span class="line"><span>global-review.md</span></span>
<span class="line"><span>aggregate-review.md</span></span></code></pre></div><p><code>pr-review-bot.md</code> 是底色。它告诉模型：你不是聊天助手，你是 whatevertogo 的替身 reviewer。你要像 maintainer 一样看 PR，优先找这次 diff 引入或暴露出来的问题，不要写泛泛建议。</p><p>这里保留了 <code>reviewnow</code> 里最重要的几条：</p><ul><li>先看真实 diff，不要凭感觉 review。</li><li>有证据再报问题，低置信度的放 observation。</li><li>从 Correctness、Security、Reliability/Performance、Tests/API Contract 几个角度看。</li><li>severity 按影响分，不要因为问题属于测试或设计就自动降成 P3。</li><li>每个 finding 都要有 evidence、project context、impact、fix。</li></ul><p>我故意没有把 Architecture 单独列出来。插件里的 global pass 会看跨文件和架构风险，但最后还是要落到具体影响上。否则模型很容易开始写“架构上建议进一步抽象”这种没法处理的废话。</p><p>剩下几份 prompt 按阶段来。orientation 先看 PR 元信息、仓库记忆、checks 和文件清单；file pass 只看当前 shard；global pass 再回头找跨文件问题；aggregate 写的是合并阶段的规矩：去重，保留最高 severity，不允许凭空创造新 finding。最后 Rust 还会再合并和校验一遍。</p><p>我后来发现，prompt 里最有用的不是“请认真 review”。这种话基本没用。真正有用的是限制：</p><ul><li>只能返回 JSON</li><li>不要调用 GitHub API</li><li>不要写最终评论</li><li>finding 必须落在给出的 <code>RIGHT</code> / <code>LEFT</code> 行上</li><li>看过的文件要写进 <code>files_reviewed</code></li><li>不要为了显得完整而写“看起来没问题”这种废话</li></ul><p>这些限制很硬，读起来也不优雅。但 prompt 如果太优雅，模型就会开始自由发挥。自由发挥在聊天里挺可爱，在自动 review 里就容易变事故。</p><p>还有一个细节：prompt 会带上 repo memory、PR memory、路径级说明和 deterministic checks。模型不是只看 diff，它会知道这个仓库以前踩过什么坑，当前 PR 有没有失败的 checks，哪些文件没有 patch、不能 inline comment。</p><p>我不追求 prompt 写得像一篇漂亮文章。它更像一份任务单：你只能看这些材料，只能输出这种格式，只能在这些位置提问题。剩下的交给 Rust 校验。</p><h2 id="发评论要克制" tabindex="-1">发评论要克制 <a class="header-anchor" href="#发评论要克制" aria-label="Permalink to &quot;发评论要克制&quot;">​</a></h2><p>默认最多发 12 条 inline comments。P3 通常只进 summary，除非触发评论明显是在要 nitpick。</p><p>这不是为了显得保守，是为了不烦人。</p><p>自动 review 很容易变成噪音。它只要连续几次刷出一堆低价值评论，大家就会开始忽略它。我的想法是，inline comment 应该留给真正需要作者停下来看的问题。其他东西放 summary，读的人自己决定要不要管。</p><p>发布时分两层：</p><p>第一层用 GitHub Pull Request Review API 发 inline comments。</p><p>第二层发 final summary，里面写这次 review 的 session、触发来源、head SHA、inline 数量、unplaced findings、验证信息和剩余风险。</p><p>如果 GitHub 拒绝 inline payload，插件不会静默失败。它会把这些 finding 转成 unplaced finding，写进 summary。难看一点，但至少人能看到。</p><h2 id="memory-不只是给模型看的" tabindex="-1">memory 不只是给模型看的 <a class="header-anchor" href="#memory-不只是给模型看的" aria-label="Permalink to &quot;memory 不只是给模型看的&quot;">​</a></h2><p>插件有 Markdown memory：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>memory/repos/&lt;owner&gt;__&lt;repo&gt;/index.md</span></span>
<span class="line"><span>memory/repos/&lt;owner&gt;__&lt;repo&gt;/pr-&lt;number&gt;.md</span></span></code></pre></div><p>repo index 记仓库层面的 review 历史。PR memory 记单个 PR 的历史。prompt 会带上这些内容，让模型知道之前说过什么。</p><p>还有一份结构化 memory 在 <code>state.json</code> 里。这里会保存已经发布过的 finding fingerprint。</p><p>这个比 Markdown memory 更硬。模型下次又提同一个问题，插件会发现 fingerprint 已经存在，然后把它打成 already posted。否则同一个 PR 每 push 一次，agent 就重复提醒一遍，谁受得了。</p><h2 id="webhook-和-polling" tabindex="-1">webhook 和 polling <a class="header-anchor" href="#webhook-和-polling" aria-label="Permalink to &quot;webhook 和 polling&quot;">​</a></h2><p>webhook 很快，但我不想只靠 webhook。</p><p>webhook 路径大概是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GitHub webhook -&gt; HMAC 校验 -&gt; delivery 去重 -&gt; event queue</span></span></code></pre></div><p>polling 做的事情更多：</p><ul><li>检查 <code>gh</code> 是否登录</li><li>搜索提到配置账号的 open PR</li><li>拉取配置仓库的 open PR</li><li>做新 PR 自动 review 的 baseline</li><li>清理旧 worktree 和旧 session</li><li>恢复卡住的 running review</li></ul><p>webhook 像门铃，polling 像巡逻。门铃响了最好，但没响也不能假装什么都没发生。</p><h2 id="prompt-编进二进制" tabindex="-1">prompt 编进二进制 <a class="header-anchor" href="#prompt-编进二进制" aria-label="Permalink to &quot;prompt 编进二进制&quot;">​</a></h2><p>review 用的几个 prompt 在 <code>prompts/</code> 目录里，然后通过 <code>include_str!</code> 编进 binary。</p><p>我不想让这个插件还依赖某个本地 skill 目录。插件安装以后，最好只依赖这些东西：插件系统、<code>gh</code>、Astrcodey、GitHub。路径依赖越少，部署时越少出现“我这里明明可以”的问题。</p><p>这也符合我对内置插件的理解：能靠插件包自己解决的，就不要去摸项目里的其他东西。</p><h2 id="结尾" tabindex="-1">结尾 <a class="header-anchor" href="#结尾" aria-label="Permalink to &quot;结尾&quot;">​</a></h2><p>这个 PR Review Agent 最让我在意的一点，是它没有把最后一道门交给模型。</p><p>模型可以说“这里可能有问题”。插件要问：行号对吗？严重性够吗？以前发过吗？会不会刷屏？GitHub 接不接受这个位置？</p><p>这些问题不适合交给模型自己回答。它太会圆了。</p><p>所以最后还是那句话：模型负责提意见，插件负责不信它。自动化 review 要是真的想进工程流程，至少得先学会这一点。</p>`,88)])])}const u=a(p,[["render",t]]);export{m as __pageData,u as default};
